            link.addEventListener('click', function(event) {
                event.preventDefault(); // 阻止默认跳转行为
                clickCount++;
                if (clickCount % 2 === 0) {
                    contentDiv.style.display = 'none'; // 偶数次点击，隐藏内容
                } else {
                    contentDiv.style.display = 'block'; // 奇数次点击，显示内容
                }
            });
        });
    });
</script>
